-- 0025: Refresh all project copy from the reviewed local zh/en data.
-- Run after migrations 0021-0024 so D1 reflects the current project content.
INSERT OR REPLACE INTO projects (id, zh, en, sort_order) VALUES ('job-radar', '{"id":"job-radar","category":"大學校外作品","title":"Job Radar — 個人化求職雷達","period":"2026","description":"每天整理 104、Cake 與 LinkedIn 的職缺，依我的技能和條件排序，附上推薦理由。清單每日更新，可按來源、職類與搜尋字詞篩選。","tags":["Python","Playwright","Cloudflare Pages","GitHub Actions","靜態生成"],"detail":{"purpose":"我想把不同求職網站的職缺放在同一張清單裡，比較條件時不用一直切換頁面。","concept":"工具從三個來源整理職缺，保留原始連結，再依技能和求職條件排序。公開頁面只顯示職缺與篩選功能；個人化分析留在私有資料中。","outcome":"Job Radar 每日更新職缺清單，讓我先查看較符合條件的職缺，再自行確認職務內容與申請狀態。","tech":[{"group":"爬蟲與聚合","items":[{"name":"104 API 逆向","desc":"舊版 joblist API 失效、公司頁為 SPA，逆向前端 bundle 找出現行 /api/companies/{code}/jobs 端點與代碼編碼規則"},{"name":"多來源整合","desc":"整理 104、Cake 與 LinkedIn 職缺，轉成一致的欄位格式。"}]},{"group":"評分與呈現","items":[{"name":"個人化評分引擎","desc":"公司適配度×關鍵字×地點×經歷×新人友善多維加權，權重外置可調；階段分桶感知畢業時程"},{"name":"靜態生成 RWD","desc":"建置時靜態渲染單檔 HTML，前端僅做過濾；桌機多欄、手機單欄；Medium 閱讀風排版"}]},{"group":"自動化與安全","items":[{"name":"雲端 CI/CD","desc":"GitHub Actions 每日 cron 爬取→建置→wrangler 部署 Cloudflare Pages，電腦關機照跑"},{"name":"伺服器端登入保護","desc":"Pages Function（_worker.js）密碼保護私密分析頁，未驗證者資料不傳輸、失敗關閉"}]}],"demo":"https://job-radar-bck.pages.dev","github":"https://github.com/Jcsk7049/job-radar"}}', '{"id":"job-radar","category":"大學校外作品","title":"Job Radar: Personalized Job Search Dashboard","period":"2026 – Present","description":"A daily list of roles from 104, Cake, and LinkedIn, ranked against my skills and criteria with a reason for each recommendation. Filter by source, role, or search term.","tags":["Python","Playwright","Web Scraping","GitHub Actions","Cloudflare Pages"],"detail":{"purpose":"I wanted one place to compare listings across job sites without switching between pages.","concept":"The tool collects roles from three sources, keeps the original links, and ranks them against my criteria. The public page shows listings and filters; personal analysis stays private.","outcome":"Job Radar refreshes the list daily. I review the suggested roles and verify each position and application status myself.","tech":[{"group":"Data Collection","items":[{"name":"104 API reverse engineering","desc":"After the old joblist API was discontinued, found the current /api/companies/{code}/jobs endpoint and company-code scheme from the company-page SPA''s frontend bundle, pulling all listings instead of keyword search"},{"name":"Playwright dynamic rendering","desc":"Cake''s job pages are JS-rendered, so I use a headless browser and wait for content to load before scraping"},{"name":"LinkedIn guest endpoint","desc":"Uses LinkedIn''s public guest job API (plain HTTP) to avoid the login wall and typical scraper blocks"}]},{"group":"Scoring & Presentation","items":[{"name":"Externalized scoring engine","desc":"Company fit, title keywords, location, experience thresholds, etc. all live in config.json, so ranking changes don''t require code edits"},{"name":"Static dashboard generation","desc":"build_dashboard.py normalizes the three sources'' JSON into one card schema and renders a single responsive HTML file; frontend JS only handles filtering/search/saved status (localStorage)"}]},{"group":"Automation & Deployment","items":[{"name":"GitHub Actions cron","desc":"A daily cron runs the full pipeline (scrape -> score -> build -> deploy); migrated from a local Windows scheduled task so it still runs with the computer off"},{"name":"CI deploy debugging","desc":"A Cloudflare deploy token with invisible characters was breaking request headers; fixed by stripping non-printable characters with tr -cd before deploy and printing the string length to diagnose"}]}],"demo":"https://job-radar-bck.pages.dev","github":"https://github.com/Jcsk7049/job-radar"}}', 0);
INSERT OR REPLACE INTO projects (id, zh, en, sort_order) VALUES ('analog-ic-studio', '{"id":"analog-ic-studio","category":"大學校外作品","title":"Analog IC Studio — 類比 IC 自動調參平台","period":"2026","description":"用 Python、Ngspice 與 SciPy 做類比電路模擬和元件尺寸搜尋，包含運算放大器、Bandgap、振盪器與 VCO。這是模擬工具；目前線上展示站無法啟動。","tags":["Python","Ngspice","sky130 PDK","SciPy","Flask"],"detail":{"purpose":"我把類比電路的模擬與調參流程整理成工具，讓使用者輸入目標後，可以比較不同元件尺寸下的模擬結果。","concept":"工具以 Ngspice 執行電路模擬，再由 SciPy 搜尋元件參數。涵蓋 AC、DC 與瞬態分析；sky130 模式使用公開 PDK。輸出是模擬結果，並非晶片實測數據。","outcome":"目前完成多種電路拓樸的模擬與參數搜尋程式。線上 Space 暫時無法使用，因此這裡不提供可操作的即時展示。","tech":[{"group":"模擬引擎","items":[{"name":"Ngspice 閉環模擬","desc":"AC/DC/瞬態自動萃取 Gain/PM/UGF、溫漂、振盪頻率；自我修復護欄偵測不收斂自動重試"},{"name":"sky130 真實 PDK","desc":"接 SkyWater sky130 開源製程（BSIM4），含 tt/ff/ss 角落，與 Level-1 快速模型雙模對照"}]},{"group":"最佳化演算法","items":[{"name":"多變量混合優化","desc":"每顆 MOS 獨立 W/L（最多 14 維），SciPy DE 全域 + Nelder-Mead 局部，多線程平行評估"},{"name":"物理護欄","desc":"強制 Wp=2~3×Wn（遷移率比）杜絕非物理解；Pelgrom 失配良率模型 σ∝1/√WL"}]},{"group":"RFIC 分析與部署","items":[{"name":"RFIC 看盤","desc":"相位雜訊（Leeson）、FTR 調諧曲線、Kvco、PVT 27 角落、帕雷托套餐、佈局 finger 拆分"},{"name":"雲端部署","desc":"Docker（apt ngspice + Flask）部署至 Hugging Face Spaces，目前線上 Space 無法啟動"}]}],"github":"https://github.com/Jcsk7049/analog-ic-studio","demo":null}}', '{"id":"analog-ic-studio","category":"大學校外作品","title":"Analog IC Studio — Automated Analog IC Tuning Platform","period":"2026","description":"A Python, Ngspice, and SciPy toolkit for simulating analog circuits and searching component sizes, including op amps, bandgap references, oscillators, and VCOs. It is a simulation tool; the hosted demo is currently unavailable.","tags":["Python","Ngspice","sky130 PDK","SciPy","Flask"],"detail":{"purpose":"I organized analog simulation and tuning into a tool where users can set a target and compare simulated results for different component sizes.","concept":"Ngspice runs circuit simulations and SciPy searches component parameters. The project covers AC, DC, and transient analysis; sky130 mode uses the open PDK. Results are simulations, not silicon measurements.","outcome":"The project includes simulation and parameter-search code for several circuit topologies. The hosted Space is currently unavailable, so there is no live demo.","tech":[{"group":"Simulation Engine","items":[{"name":"Ngspice closed-loop","desc":"AC/DC/transient auto-extract Gain/PM/UGF, drift, frequency; self-healing guard retries on non-convergence"},{"name":"Real sky130 PDK","desc":"SkyWater sky130 open process (BSIM4) with tt/ff/ss corners, paired with a fast Level-1 model"}]},{"group":"Optimization","items":[{"name":"Multi-variable hybrid","desc":"Per-instance W/L (up to 14-D), SciPy DE global + Nelder-Mead local, parallel multi-threaded eval"},{"name":"Physics guard","desc":"Enforces Wp=2-3x Wn (mobility ratio); Pelgrom mismatch yield model, sigma ~ 1/sqrt(WL)"}]},{"group":"RFIC & Deployment","items":[{"name":"RFIC dashboard","desc":"Phase noise (Leeson), FTR tuning curve, Kvco, 27-corner PVT, Pareto packages, finger splitting"},{"name":"Cloud deploy","desc":"Docker (apt ngspice + Flask) on Hugging Face Spaces; currently unavailable"}]}],"github":"https://github.com/Jcsk7049/analog-ic-studio","demo":null}}', 1);
INSERT OR REPLACE INTO projects (id, zh, en, sort_order) VALUES ('vap', '{"id":"vap","featured":true,"cover":"/images/vap/cover-ai.jpg","category":"大學專題作品","title":"ICU VAP 早期預測：試驗性方法論驗證研究","period":"2025 – 現在","description":"亞東紀念醫院單中心 ICU 研究，資料共 107 人。論文接受後，我重新檢查資料索引、時間對齊與驗證切分，發現視窗層切分和病人來源差異會讓結果偏高；因此不把現有結果當成臨床預測效能。研究獲 IEEE GCCE 2026 poster 接受。","badge":"IEEE GCCE 2026 · Poster","tags":["LSTM · Time-Series","Integrated Gradients","Stay-Level CV","SMOTE","Medical AI"],"detail":{"images":[{"src":"/images/vap/fig-pipeline.png","caption":"系統流程：特徵篩選 → 滑動視窗 → LSTM → 多時程評估"},{"src":"/images/vap/fig-lstm-vs-baseline.png","caption":"原論文視窗層基準比較；同一病人跨訓練/測試集，複查後不作效能主張"},{"src":"/images/vap/fig-lstm-performance.png","caption":"原論文視窗層結果圖；評估設定複查後，數字不代表病人層泛化效能"}],"purpose":"研究原本想評估 ICU 時序資料能否預測 VAP。投稿後的複查發現資料處理和評估條件有問題，於是把重點轉為檢查這些條件如何影響模型結果。","concept":"我重新核對病人、時間窗與標籤的對應，也檢查同一病人是否同時出現在訓練與測試資料。分析還發現呼吸器廠牌和收案年份與標籤有關，現有資料無法排除來源差異的影響。","outcome":"這項研究目前能支持的是評估流程的限制：視窗層切分可能高估表現，資料來源也可能成為捷徑。若要判斷臨床訊號，仍需要來源一致、時間定義清楚的資料。論文獲 IEEE GCCE 2026 poster 接受。","tech":[{"group":"深度學習","items":[{"name":"LSTM 時序建模","desc":"以 TensorFlow / Keras 建立三層 LSTM 時序分類模型，並比較不同窗口與簡化模型；在小型單中心資料上的結果需要配合同病人切分與來源分層解讀。"},{"name":"類別不平衡處理","desc":"在訓練折內使用 SMOTE，避免合成樣本跨越訓練與測試邊界。後續比較未能證明 GAN 或其他擴增方式優於不擴增或 SMOTE。"},{"name":"可解釋 AI（XAI）","desc":"以 Integrated Gradients 歸因各特徵對每筆預測的貢獻，進而設計 Ablation Study 驗證 Top 4 特徵的不可取代性"}]},{"group":"實驗設計","items":[{"name":"防洩漏驗證設計","desc":"以病人為單位切分資料，檢查同一病人是否跨越訓練與測試集。MIMIC-IV 復刻與亞東資料的分析屬不同實驗；目前不以其結果主張臨床預測效能。"},{"name":"Per-fold 正規化","desc":"在交叉驗證各折內計算正規化統計量，避免測試折統計量進入訓練流程。"},{"name":"Ablation Study","desc":"曾在視窗層設定下移除 mv_total（mv≡Vt×RR），觀察到 AUROC 與 AUPRC 上升；此分析未在修正後的病人層設定重跑，不作為目前結論。"}]},{"group":"特徵工程","items":[{"name":"滑動視窗建構","desc":"將 ICU 時序資料轉成固定長度窗口，並依預測時間點建立輸入資料；窗口切分須以病人為群組，避免同一病人跨折。"},{"name":"生理訊號前處理","desc":"使用 pandas / NumPy 整理多來源生命徵象與呼吸器資料；稽核中修正時間對齊與欄位覆寫問題，顯示前處理需逐來源核對。"}]}],"github":""}}', '{"id":"vap","featured":true,"cover":"/images/vap/cover-ai.jpg","category":"大學專題作品","title":"ICU VAP Prediction: Pilot Methodology Validation","period":"2025 – Present","description":"A single-center ICU study at Far Eastern Memorial Hospital with 107 patients. After acceptance, I reviewed indexing, time alignment, and evaluation splits and found that window-level splitting and differences in patient sources could inflate results. The current data do not support a clinical performance claim. Accepted as an IEEE GCCE 2026 poster.","badge":"IEEE GCCE 2026 · Poster","tags":["LSTM · Time-Series","Integrated Gradients","Stay-Level CV","SMOTE","Medical AI"],"detail":{"images":[{"src":"/images/vap/fig-pipeline.png","caption":"Pipeline: feature selection → sliding window → LSTM → multi-horizon evaluation"},{"src":"/images/vap/fig-lstm-vs-baseline.png","caption":"Original window-level baseline comparison; patients crossed the train/test split, so these are not performance claims"},{"src":"/images/vap/fig-lstm-performance.png","caption":"Original window-level result plot; the audited setup does not establish patient-level generalization"}],"purpose":"The study began by asking whether ICU time series could predict VAP. A post-submission audit found issues in data processing and evaluation, so I examined how those conditions affected the results.","concept":"I checked patient, time-window, and label alignment, and whether the same patient appeared in both training and test data. Ventilator brand and enrollment year were also associated with labels, so source effects cannot be ruled out.","outcome":"The study currently supports conclusions about evaluation limits: window-level splitting can inflate scores, and source differences may provide shortcuts. Assessing clinical signals will require consistent sources and clear time definitions. Accepted as an IEEE GCCE 2026 poster.","tech":[{"group":"Deep Learning","items":[{"name":"LSTM Time-Series Modeling","desc":"Built a three-layer TensorFlow/Keras LSTM classifier and compared window lengths and smaller models. Results on this small single-center cohort require patient-level splitting and source-stratified interpretation."},{"name":"Class Imbalance Handling","desc":"Applied SMOTE within each training fold to keep synthetic samples out of test folds. Later experiments did not establish that GAN or other augmentation methods outperform no augmentation or SMOTE."},{"name":"Explainable AI (XAI)","desc":"Integrated Gradients was used to inspect feature contributions. Feature selection and attribution rankings were affected by full-dataset selection and data-processing issues, so the Top 4 ranking is not treated as stable."}]},{"group":"Experimental Design","items":[{"name":"Leakage-Free Validation","desc":"Used patient-level splits to check whether one patient crossed the training and test sets. The MIMIC-IV replication and FEMH analysis are separate experiments; neither is used here to claim clinical prediction performance."},{"name":"Per-fold Normalization","desc":"Computed normalization statistics independently inside each cross-validation fold to keep test-fold statistics out of training."},{"name":"Ablation Study","desc":"Removing mv_total (mv≡Vt×RR) improved AUROC and AUPRC under the window-level setup. This analysis was not rerun with the corrected patient-level evaluation and is not a current conclusion."}]},{"group":"Feature Engineering","items":[{"name":"Sliding Window Construction","desc":"Converted ICU time series into fixed-length windows for each prediction horizon. Splits must group by patient so windows from one patient cannot cross folds."},{"name":"Physiological Signal Preprocessing","desc":"Used pandas and NumPy to prepare multi-source vital-sign and ventilator data. The audit corrected time-alignment and field-overwrite issues, showing why each source needs explicit checks."}]}],"github":""}}', 2);
INSERT OR REPLACE INTO projects (id, zh, en, sort_order) VALUES ('aws-hackathon', '{"id":"aws-hackathon","cover":"/images/AWS-bito-guard/dashboard-cover.png","category":"大學校外作品","title":"AWS x BitoPro 黑客松：BitOGuard","period":"2026","description":"三人團隊參加 AWS × BitoPro 黑客松並進入決賽，最後完賽，沒有名次。系統以 LightGBM 與 XGBoost 混合模型分析交易帳戶，加入 32 項行為特徵，並以 SHAP 檢視預測依據。","tags":["LightGBM","XGBoost","AWS SageMaker","AWS Glue","SHAP","Streamlit"],"detail":{"images":[{"src":"/images/AWS-bito-guard/dashboard-overview.png","caption":"數據總覽：AUC 83.2%、Precision 27.5%、Recall 33.2%，混淆矩陣 + 5-Fold CV 柱狀圖"},{"src":"/images/AWS-bito-guard/dashboard-risk-query.png","caption":"帳號風險查詢：USER ID 971465 評分 82.1%，判定極高風險、標記黑名單"},{"src":"/images/AWS-bito-guard/dashboard-risk-table.png","caption":"風險排名：Top 50 高風險帳號（CRITICAL）與 Top 50 低風險帳號對比"},{"src":"/images/AWS-bito-guard/dashboard-model-eval.png","caption":"模型評估：特徵重要性（total_volume 最高）+ 決策門檻分析（最佳門檻 0.24）"},{"src":"/images/AWS-bito-guard/dashboard-predictions.png","caption":"預測結果：12,753 位用戶，501 筆標記風險（3.93%）、12,252 筆正常（96.07%）"}],"purpose":"題目是從交易資料找出可能的人頭帳戶。我負責模型、資料處理和部分雲端流程，團隊把結果整理成可供審查的風險分數與儀表板。","concept":"模型使用 LightGBM 與 XGBoost 以 0.6/0.4 加權，搭配 32 項交易行為特徵。專案也包含 S3、Glue、Athena、SageMaker、Lambda 與 Streamlit 等流程；SHAP 用來查看特徵對預測的貢獻。","outcome":"團隊進入決賽並完成競賽，未獲名次。5-fold OOF AUROC 為 0.832，Precision 為 27.5%、Recall 為 33.2%；這些是競賽資料上的模型結果，不代表實際金融機構部署成效。","tech":[{"group":"機器學習","items":[{"name":"梯度提升二元分類","desc":"以 LightGBM 與 XGBoost 0.6/0.4 加權混合，並調整類別權重與分類門檻，觀察 Precision 和 Recall 的取捨。"},{"name":"行為特徵工程","desc":"從台幣與 USDT 交易記錄中萃取 32 項行為指標（交易頻率、深夜比例、黑名單鄰居數等），驗證特徵從初版 3 項擴充後對模型的實際增益"},{"name":"SHAP 可解釋性","desc":"以 SHAP 檢視整體特徵重要性，以及個別帳戶預測中的特徵貢獻。"}]},{"group":"雲端架構","items":[{"name":"端對端資料管線","desc":"串接 S3、Glue、Athena、SageMaker 與 Lambda 處理資料及模型推論，並以 CloudFormation 描述雲端資源。"},{"name":"圖形化多跳關聯分析","desc":"以 Glue + Athena SQL 實作黑名單鄰居的二階連結查詢，理解圖論特徵在關聯式資料庫中的近似計算方式與查詢複雜度"},{"name":"事件驅動推論","desc":"Lambda 接收觸發事件後呼叫 SageMaker 端點完成即時預測，理解冷啟動延遲與同步/非同步呼叫對 AML 即時偵測場景的取捨"}]}],"github":"https://github.com/Jcsk7049/bitoguard-aml","demo":"https://bitoguard-aml-kykw6kfawalbeq8vjy6yv8.streamlit.app/","pipeline":[{"marker":"①","file":"ingest_to_s3.py","label":"BitoPro API 擷取 → S3 原始資料層"},{"marker":"②","file":"glue_graph_hops.py","label":"Glue ETL + 圖形化多跳關聯分析"},{"marker":"③","file":"athena_graph_hops.sql","label":"Athena 查詢聚合特徵結果"},{"marker":"④","file":"SageMaker","label":"LightGBM 訓練與調參"},{"marker":"⑤","file":"lambda_diagnosis.py","label":"即時推論與事件觸發"},{"marker":"⑥","file":"Bedrock + SHAP","label":"自動產生可解釋性報告"},{"marker":"⑦","file":"app.py","label":"Streamlit 互動風險審查介面"},{"marker":"⑧","file":"template.yaml","label":"CloudFormation IaC"}]}}', '{"id":"aws-hackathon","cover":"/images/AWS-bito-guard/dashboard-cover.png","category":"大學校外作品","title":"AWS × BitoPro Hackathon: BitOGuard","period":"2026","description":"Our three-person team reached the AWS × BitoPro Hackathon final and completed the event without placing. The system combines LightGBM and XGBoost, analyzes transaction accounts, uses 32 behavioral features, and applies SHAP to inspect model predictions.","tags":["LightGBM","XGBoost","AWS SageMaker","AWS Glue","SHAP","Streamlit"],"detail":{"images":[{"src":"/images/AWS-bito-guard/dashboard-overview.png","caption":"Dashboard overview: AUC 83.2%, Precision 27.5%, Recall 33.2%, confusion matrix + 5-fold CV bar chart"},{"src":"/images/AWS-bito-guard/dashboard-risk-query.png","caption":"Account risk query: USER ID 971465 scored 82.1% — classified as extreme high risk, blacklisted"},{"src":"/images/AWS-bito-guard/dashboard-risk-table.png","caption":"Risk ranking: Top 50 high-risk (CRITICAL) vs. Top 50 low-risk accounts"},{"src":"/images/AWS-bito-guard/dashboard-model-eval.png","caption":"Model evaluation: feature importance (total_volume highest) + decision threshold analysis (optimal 0.24)"},{"src":"/images/AWS-bito-guard/dashboard-predictions.png","caption":"Predictions: 12,753 users — 501 flagged as risk (3.93%), 12,252 normal (96.07%)"}],"purpose":"The challenge was to identify potentially fraudulent accounts from transaction data. I worked on the model, data processing, and parts of the cloud workflow; the team presented risk scores in a review dashboard.","concept":"The model blends LightGBM and XGBoost at 0.6/0.4 and uses 32 behavioral features. The project also includes S3, Glue, Athena, SageMaker, Lambda, and Streamlit components. SHAP shows feature contributions to predictions.","outcome":"The team reached the final and completed the event, without a placement. Five-fold OOF AUROC was 0.832, with 27.5% precision and 33.2% recall. These are competition dataset results, not evidence of deployment in a financial institution.","tech":[{"group":"Machine Learning","items":[{"name":"Gradient Boosting Classification","desc":"LightGBM for imbalanced binary classification; tune max_depth, learning_rate, num_iterations, and class weighting, then compare precision and recall across decision thresholds"},{"name":"Behavioral Feature Engineering","desc":"Extracting 32 behavioral indicators from TWD and USDT transaction records (frequency, late-night ratio, blacklist neighbor count, etc.), verifying actual model gains from expanding the initial 3-feature set"},{"name":"SHAP Interpretability","desc":"Computing each feature''s marginal contribution per account; distinguishing global feature importance from per-account local explanations to support AML compliance reporting"}]},{"group":"Cloud Architecture","items":[{"name":"End-to-End Data Pipeline","desc":"Designed S3→Glue ETL→Athena→SageMaker→Lambda 6-service chain; mastering data format transformation, error propagation, and permission design between nodes; CloudFormation IaC for reproducibility"},{"name":"Graph-Based Multi-hop Analysis","desc":"Glue + Athena SQL for second-degree blacklist neighbor query; understanding the approximate computation of graph-theory features in relational databases and query complexity"},{"name":"Event-Driven Inference","desc":"Lambda receives trigger events and calls SageMaker endpoints for real-time prediction; understanding cold-start latency and sync/async tradeoffs for AML real-time detection"}]}],"github":"https://github.com/Jcsk7049/bitoguard-aml","demo":"https://bitoguard-aml-kykw6kfawalbeq8vjy6yv8.streamlit.app/","pipeline":[{"marker":"①","file":"ingest_to_s3.py","label":"BitoPro API ingestion -> S3 raw layer"},{"marker":"②","file":"glue_graph_hops.py","label":"Glue ETL + graph multi-hop analysis"},{"marker":"③","file":"athena_graph_hops.sql","label":"Athena feature aggregation query"},{"marker":"④","file":"SageMaker","label":"LightGBM training & tuning"},{"marker":"⑤","file":"lambda_diagnosis.py","label":"Real-time inference & event trigger"},{"marker":"⑥","file":"Bedrock + SHAP","label":"Auto-generated explainability report"},{"marker":"⑦","file":"app.py","label":"Streamlit interactive risk review UI"},{"marker":"⑧","file":"template.yaml","label":"CloudFormation IaC"}]}}', 3);
INSERT OR REPLACE INTO projects (id, zh, en, sort_order) VALUES ('teammatch', '{"id":"teammatch","category":"大學校外作品","title":"TeamMatch — 黑客松找隊友平台","period":"2026","description":"三人團隊在 OpenAI Build Week 社群黑客松的一天內完成 TeamMatch。我負責個人檔案、導覽和登入展示流程，也協助排除整合配對頁時遇到的 Firestore 連線問題。登入是切換既有示範身分，並非正式帳號驗證。","tags":["Next.js","TypeScript","Firebase Firestore","Tailwind CSS","介面契約"],"detail":{"purpose":"我們想做一個讓黑客松參與者快速找到隊友的配對頁，並在一天內完成可操作的展示版本。","concept":"網站以 Next.js 和 Firebase 建置，包含個人檔案、配對瀏覽和示範登入。登入流程選取預先建立的個人檔案，不使用 Firebase Authentication；這是原型，沒有正式部署或完整權限規則。","outcome":"一天內完成可展示的主要流程。我負責個人檔案、導覽與身分切換介面，並在整合時協助處理 Firestore WebChannel 連線問題。","tech":[{"group":"介面契約","items":[{"name":"開工前凍結規格","desc":"collection 名稱、camelCase 欄位、Document ID 組法、API 簽名、路由路徑先定死寫成 SPEC.md；頁面實作各自自由，合併時不必改對方的檔案"},{"name":"複合 Document ID 去重","desc":"報名 {eventId}__{userId}、滑卡 {eventId}__{swiperId}__{targetId}、配對 {eventId}__{userA}__{userB}（兩個 ID 先排序）；重複操作變成覆蓋同一筆，不需額外的去重查詢或交易"}]},{"group":"登入與個人檔案（我負責）","items":[{"name":"Demo 身分切換","desc":"不接 Firebase Auth，列出 profiles 讓人選一張卡進站、localStorage 存 currentUserId；換到 demo 當下能立刻多人互相配對，代價是沒有真正的驗證"},{"name":"Firestore 直讀寫表單","desc":"getDoc / updateDoc 編輯個人檔案，技能逗號字串轉陣列並即時預覽；頭像用 DiceBear 依 avatarSeed 生成，免上傳與 Storage"},{"name":"導覽列狀態同步","desc":"依 pathname 高亮並重讀當前 profile；非同步載入用 cancelled 旗標，避免元件卸載後才 setState"}]},{"group":"整合與除錯","items":[{"name":"Firestore 強制長輪詢","desc":"預設 WebChannel 串流建不起來，改 initializeFirestore 帶 experimentalForceLongPolling 才能穩定讀寫"},{"name":"三分支合併收尾","desc":"把三人分支併回主線，補上聯絡欄位、活動人數上限（隊伍人數加總而非報名筆數）、已有隊友者不進滑卡池，並同步更新 SPEC"}]}],"github":"https://github.com/CHU-BO-YU/teamder"}}', '{"id":"teammatch","category":"大學校外作品","title":"TeamMatch — Hackathon Teammate Finder","period":"2026","description":"Built in one day by a three-person team at an OpenAI Build Week community hackathon. I handled profiles, navigation, and the demo login flow, and helped resolve a Firestore connection issue during swipe-page integration. Login switches between demo profiles; it is not real authentication.","tags":["Next.js","TypeScript","Firebase Firestore","Tailwind CSS","Interface Contract"],"detail":{"purpose":"We wanted a page where hackathon participants could quickly find teammates, and completed a working demo in one day.","concept":"Built with Next.js and Firebase, the site includes profiles, browsing, and a demo login flow. Login selects a preset profile and does not use Firebase Authentication. This is a prototype without production deployment or complete security rules.","outcome":"We completed the main demo flow in one day. I worked on profiles, navigation, and identity switching, and helped troubleshoot Firestore WebChannel during integration.","tech":[{"group":"Interface Contract","items":[{"name":"Spec frozen before coding","desc":"Collection names, camelCase fields, document ID composition, API signatures, and route paths were fixed in SPEC.md; page implementation stayed free, so merging never required editing someone else''s files"},{"name":"Composite document IDs for idempotency","desc":"Registration {eventId}__{userId}, swipe {eventId}__{swiperId}__{targetId}, match {eventId}__{userA}__{userB} with the IDs sorted first; a repeated action overwrites the same document, so no dedup queries or transactions are needed"}]},{"group":"Login & Profile (my slice)","items":[{"name":"Demo identity switcher","desc":"No Firebase Auth: the login page lists profiles, picking a card signs you in as that user, and currentUserId lives in localStorage — traded real authentication for several people being able to match each other on the spot"},{"name":"Forms writing straight to Firestore","desc":"getDoc / updateDoc for profile editing, comma-separated skills parsed into an array with a live pill preview, and DiceBear avatars derived from avatarSeed instead of uploads"},{"name":"Navbar state sync","desc":"Highlights by pathname and reloads the current profile on navigation; the async load uses a cancelled flag so it never calls setState after unmount"}]},{"group":"Integration & Debugging","items":[{"name":"Forced Firestore long polling","desc":"The default WebChannel stream wouldn''t establish; passing experimentalForceLongPolling to initializeFirestore was what made reads and writes stable"},{"name":"Merging three branches","desc":"Merged all three branches back into main and added the contact fields, event capacity (summed team sizes rather than registration count), and exclusion of already-teamed users from the swipe pool, updating the SPEC to match"}]}],"github":"https://github.com/CHU-BO-YU/teamder"}}', 4);
INSERT OR REPLACE INTO projects (id, zh, en, sort_order) VALUES ('audio-amplifier', '{"id":"audio-amplifier","cover":"/images/audio-amplifier/circuit-assembled.jpg","category":"大學課程作品","title":"類比電路實作：音訊放大器 PCB 設計","period":"2024","description":"大二電子電路實驗的兩級 BJT 音訊放大器。隊友做麵包板與 PSpice；我整理原理圖、佈 PCB、蝕刻、焊接並除錯。重做兩次後排除殘銅短路與元件腳位鏡像問題，最後以 8Ω 喇叭確認能播放聲音。","tags":["BJT 放大電路","PCB Layout","感光板製作","電路模擬","SPICE"],"detail":{"images":[{"src":"/images/audio-amplifier/circuit-assembled.jpg","caption":"完成品：BJT 兩級放大電路板 + 8Ω 喇叭，實際驅動音訊輸出"},{"src":"/images/audio-amplifier/pcb-etched.png","caption":"感光板酸洗蝕刻後的 PCB 生板：走線清晰，準備鑽孔焊接"},{"src":"/images/audio-amplifier/circuit-schematic.png","caption":"EDA 電路原理圖：CE 放大級 + 偏壓網路 + CC 射極隨耦器完整設計"},{"src":"/images/audio-amplifier/pcb-layout-components.png","caption":"PCB 元件配置圖（正面）：109.2 × 45.7 mm，含電晶體、電容、可變電阻佈局"},{"src":"/images/audio-amplifier/pcb-layout-bottom.png","caption":"PCB 元件配置圖（底面）：確認元件腳位鏡像方向，兩次重製的關鍵學習點"},{"src":"/images/audio-amplifier/pcb-traces.png","caption":"PCB 銅箔走線圖：CE 放大級 + CC 射極隨耦器完整佈線"},{"src":"/images/audio-amplifier/pcb-drill-pattern.png","caption":"PCB 鑽孔孔位圖：所有元件腳位與固定孔的加工基準"}],"purpose":"課程要求製作兩級 BJT 音訊放大器。我負責把電路圖轉成 PCB，完成實板製作與故障排查。","concept":"工作包含原理圖整理、PCB 佈線、感光板曝光蝕刻、元件焊接與上電檢查。第一次重做處理板上殘銅造成的短路，第二次修正元件封裝方向。","outcome":"完成的電路接上 8Ω 喇叭後能播放聲音。這次實作讓我走過從電路圖、PCB 到實板除錯的完整流程。","tech":[{"group":"類比電路設計","items":[{"name":"CE 放大器偏壓設計","desc":"計算 R3 / R4 分壓偏壓使 Q1 穩定工作於主動區，理解 β 值、直流工作點與熱穩定度三者在選值時的取捨"},{"name":"CC 射極隨耦器","desc":"以發射極電阻 RE 引入負回授實現低輸出阻抗，有效降低前後級的負載效應，電壓增益接近 1"},{"name":"偏壓穩定設計","desc":"D1–D4 串聯提供穩定電壓差給 Q2/Q3 基極；C3 吸收關斷瞬間反向電壓，理解二極體正向壓降的溫度特性對偏壓穩定度的影響"},{"name":"可變增益調整","desc":"Rv1a/Rv1b 控制輸入信號強度，Rv2 微調直流工作點，實驗中在不失真前提下找到最大線性增益的操作邊界"}]},{"group":"PCB 製作","items":[{"name":"Layout 佈線設計","desc":"手工繪製雙面 PCB，以元件下方走線策略減少白線交叉點，實際走完曝光→顯影→酸洗蝕刻製程"},{"name":"系統性電路除錯","desc":"兩次重製建立從元件逐一驗證（導通、飽和、充能）到板層短路定位的除錯流程，分別識別殘銅短路與腳位鏡像兩種根本原因"}]},{"group":"量測與驗證","items":[{"name":"電路模擬與實測對比","desc":"先以 SPICE 模擬時域波形與頻率響應波德圖，再以示波器量測實際輸出，分析非理想元件特性（電阻溫度係數、電容漏電流）對結果造成的偏差"}]}],"github":""}}', '{"id":"audio-amplifier","cover":"/images/audio-amplifier/circuit-assembled.jpg","category":"大學課程作品","title":"Analog Circuit Implementation: Audio Amplifier PCB Design","period":"2024","description":"A two-stage BJT audio amplifier for a sophomore electronics lab. My teammate handled the breadboard and PSpice; I prepared the schematic, routed the PCB, etched and soldered the board, and debugged it. Two rebuilds fixed a copper short and mirrored component footprints; an 8Ω speaker played audio.","tags":["BJT Amplifier","PCB Layout","Photoresist Etching","Circuit Simulation","SPICE"],"detail":{"images":[{"src":"/images/audio-amplifier/circuit-assembled.jpg","caption":"Final product: two-stage BJT amplifier board + 8Ω speaker, driving audio output"},{"src":"/images/audio-amplifier/pcb-etched.png","caption":"Photoresist-etched PCB blank: clear traces, ready for drilling and soldering"},{"src":"/images/audio-amplifier/circuit-schematic.png","caption":"EDA schematic: CE amplifier stage + bias network + CC emitter follower"},{"src":"/images/audio-amplifier/pcb-layout-components.png","caption":"PCB component placement (top): 109.2×45.7mm, transistors, capacitors, trimpots"},{"src":"/images/audio-amplifier/pcb-layout-bottom.png","caption":"PCB component placement (bottom): confirming mirrored pin orientation — key lesson from two rebuilds"},{"src":"/images/audio-amplifier/pcb-traces.png","caption":"PCB copper traces: full routing for CE + CC stages"},{"src":"/images/audio-amplifier/pcb-drill-pattern.png","caption":"PCB drill pattern: all component pads and mounting hole machining reference"}],"purpose":"The lab required a two-stage BJT audio amplifier. I translated the circuit into a PCB and made and debugged the physical board.","concept":"My work covered schematic cleanup, PCB routing, photoresist etching, soldering, and power-on checks. The first rebuild fixed a short from residual copper; the second corrected component footprint orientation.","outcome":"The finished circuit played through an 8Ω speaker. I worked through the full path from schematic and PCB layout to hardware debugging.","tech":[{"group":"Analog Circuit Design","items":[{"name":"CE Amplifier Bias Design","desc":"Calculating R3/R4 voltage divider bias to stabilize Q1 in active region; understanding the tradeoffs between β, DC operating point, and thermal stability in component selection"},{"name":"CC Emitter Follower","desc":"Emitter resistor RE introduces negative feedback for low output impedance, reducing loading effects between stages; voltage gain approaches 1"},{"name":"Bias Stabilization Design","desc":"D1–D4 in series provide stable voltage difference to Q2/Q3 bases; C3 absorbs turn-off transient reverse voltage; understanding how diode forward voltage temperature characteristics affect bias stability"},{"name":"Variable Gain Adjustment","desc":"Rv1a/Rv1b control input signal strength; Rv2 fine-tunes DC operating point; experimentally finding the maximum linear gain boundary without distortion"}]},{"group":"PCB Fabrication","items":[{"name":"Layout Routing Design","desc":"Hand-drawn double-sided PCB; routing under components to reduce white-line crossings; completed full exposure→development→acid etching process"},{"name":"Systematic Circuit Debugging","desc":"Two rebuilds established a debugging flow from component-by-component verification (continuity, saturation, charge) to board-layer short detection; identified residual-copper shorts and pin mirror errors as root causes"}]},{"group":"Measurement & Verification","items":[{"name":"Simulation vs. Real-World Comparison","desc":"SPICE simulation of time-domain waveform and Bode plot frequency response, then oscilloscope measurement of actual output; analyzing deviations caused by non-ideal component characteristics"}]}],"github":""}}', 5);
INSERT OR REPLACE INTO projects (id, zh, en, sort_order) VALUES ('pcb-defect-detection', '{"id":"pcb-defect-detection","cover":"/images/pcb-defect-detection/cover.png","category":"大學課程作品","title":"PCB 線路瑕疵偵測：Azure Custom Vision 切塊物件偵測","period":"2026","description":"用 Azure Custom Vision 偵測 PCB 缺孔、鼠咬與斷路。訓練時將影像切成 600px 區塊，推論時以重疊視窗掃描並用 NMS 合併框，另做 Flask 批次檢查與人工回饋重訓流程。README 報告 mAP 82%、Precision 100%。","tags":["Azure Custom Vision","Object Detection","影像切塊 Tiling","model.pb · TensorFlow","Pascal VOC"],"detail":{"images":[{"src":"/images/pcb-defect-detection/performance.png","caption":"Custom Vision 訓練評估摘要：公開 README 報告 Precision 100%、mAP 82%"},{"src":"/images/pcb-defect-detection/pipeline.png","caption":"檢測工具與人工回饋重訓流程：上傳→切塊偵測→批量統計→人工校正→審核核准→只用核准資料重訓"},{"src":"/images/pcb-defect-detection/dataset.png","caption":"訓練資料：每張大圖以缺陷為中心切成 600px 塊，缺陷框佔比從約 2% 拉到約 12%（綠框為標註）"},{"src":"/images/pcb-defect-detection/validation-zoom.png","caption":"未參與訓練的板型 09–12 驗證（放大）：綠＝標註、紅＝模型預測，三類缺陷定位清楚"},{"src":"/images/pcb-defect-detection/validation-board.png","caption":"整板偵測：對 held-out 板（型號 09）做切塊推論後把框映射回原圖的完整結果"},{"src":"/images/pcb-defect-detection/missing-hole/09_01.jpg","caption":"missing_hole 偵測：板型 09 第 1 張（綠＝標註，紅＝模型預測）"},{"src":"/images/pcb-defect-detection/missing-hole/11_01.jpg","caption":"missing_hole 偵測：板型 11 第 1 張（綠＝標註，紅＝模型預測）"},{"src":"/images/pcb-defect-detection/mouse-bite/09_01.jpg","caption":"mouse_bite 偵測：板型 09 第 1 張（綠＝標註，紅＝模型預測）"},{"src":"/images/pcb-defect-detection/mouse-bite/11_01.jpg","caption":"mouse_bite 偵測：板型 11 第 1 張（綠＝標註，紅＝模型預測）"},{"src":"/images/pcb-defect-detection/open-circuit/09_01.jpg","caption":"open_circuit 偵測：板型 09 第 1 張（綠＝標註，紅＝模型預測）"},{"src":"/images/pcb-defect-detection/open-circuit/11_01.jpg","caption":"open_circuit 偵測：板型 11 第 1 張（綠＝標註，紅＝模型預測）"}],"purpose":"整板影像尺寸太大，不適合直接交給物件偵測模型。我把訓練資料切塊，並讓推論流程掃描整板後合併重複框。","concept":"訓練流程產生 600px 影像區塊；推論使用重疊視窗，最後以 NMS 整理重疊偵測框。Flask 工具支援批次檢查與人工回饋。README 所列指標來自專案評估，不能直接視為所有板型上的保證。","outcome":"專案 README 報告 mAP 82% 與 Precision 100%，並展示保留板型的驗證。系統包含影像切塊、整板掃描、結果整理和回饋流程。","tech":[{"group":"影像處理","items":[{"name":"影像切塊 Tiling","desc":"以缺陷框為中心切 600px 塊，框需 ≥40% 面積落在塊內才保留，座標換算回塊內 0–1；缺陷佔比從約 2% 提升到約 12%，是整個專案成敗的關鍵"},{"name":"Pascal VOC 解析","desc":"用 xml.etree.ElementTree 解析 bndbox，把像素座標換算成 Custom Vision 要求的 0–1 正規化座標"}]},{"group":"雲端 AI 服務","items":[{"name":"Azure Custom Vision SDK","desc":"用 Python SDK 走完建專案（compact domain）、批次上傳含框影像、Advanced Training、發布、匯出 TensorFlow 的完整流程；刻意用 Advanced 而非 Quick Train"},{"name":"model.pb 匯出與 Colab 載入","desc":"匯出凍結圖 model.pb（輸入 Placeholder:0、輸出 model_outputs:0），在 Colab 以 tf.compat.v1 載入；YOLO 風格輸出的 anchors／NMS 解碼沿用官方 object_detection.py"}]},{"group":"推論與驗證","items":[{"name":"切塊推論 + NMS","desc":"整板切塊逐塊偵測，預測框映射回原圖，再以 IoU 0.3 的 NMS 去除重疊塊造成的重複框"},{"name":"Held-out 驗證","desc":"用模型沒看過的板型 09–12 共 106 張做泛化測試，疊綠（標註）紅（預測）框輸出；標準答案 538 個缺陷對模型輸出 509 個，直接驗證在新板上的表現而不是只信交叉驗證的數字"}]},{"group":"應用工具","items":[{"name":"批量檢測介面","desc":"Flask 本機網頁，拖曳多張板子批量偵測、分色框出三類缺陷、彙整 NG/OK 與各類數量並匯出 CSV"},{"name":"人工回饋迴圈","desc":"檢出結果可標記多抓(誤報)與漏抓(補框)存成校正資料；經人工審核核准後只用核准資料重訓，形成 active-learning 閉環"}]}],"github":""}}', '{"id":"pcb-defect-detection","cover":"/images/pcb-defect-detection/cover.png","category":"大學課程作品","title":"PCB Trace Defect Detection: Tiled Object Detection with Azure Custom Vision","period":"2026","description":"Uses Azure Custom Vision to detect missing holes, mouse bites, and open circuits in PCB images. Training images are split into 600px tiles; inference scans overlapping windows and merges boxes with NMS. A Flask tool supports batch inspection and feedback. The README reports 82% mAP and 100% precision.","tags":["Azure Custom Vision","Object Detection","Image Tiling","model.pb · TensorFlow","Pascal VOC"],"detail":{"images":[{"src":"/images/pcb-defect-detection/performance.png","caption":"Custom Vision training summary: the public README reports 100% precision and 82% mAP"},{"src":"/images/pcb-defect-detection/pipeline.png","caption":"Inspection tool & human-feedback retrain loop: upload → tiled detect → batch stats → manual correction → review/approve → retrain on approved data only"},{"src":"/images/pcb-defect-detection/dataset.png","caption":"Training data: each board is sliced into 600px tiles centered on defects, raising defect-to-tile ratio from ~2% to ~12% (green = ground truth)"},{"src":"/images/pcb-defect-detection/validation-zoom.png","caption":"Held-out boards 09–12 (zoomed): green = ground truth, red = model prediction, across all three defect classes"},{"src":"/images/pcb-defect-detection/validation-board.png","caption":"Full-board detection: tiled inference on a held-out board (type 09) with boxes mapped back to the original image"},{"src":"/images/pcb-defect-detection/missing-hole/09_01.jpg","caption":"missing_hole detection — board 09, #1 (green = ground truth, red = prediction)"},{"src":"/images/pcb-defect-detection/missing-hole/11_01.jpg","caption":"missing_hole detection — board 11, #1 (green = ground truth, red = prediction)"},{"src":"/images/pcb-defect-detection/mouse-bite/09_01.jpg","caption":"mouse_bite detection — board 09, #1 (green = ground truth, red = prediction)"},{"src":"/images/pcb-defect-detection/mouse-bite/11_01.jpg","caption":"mouse_bite detection — board 11, #1 (green = ground truth, red = prediction)"},{"src":"/images/pcb-defect-detection/open-circuit/09_01.jpg","caption":"open_circuit detection — board 09, #1 (green = ground truth, red = prediction)"},{"src":"/images/pcb-defect-detection/open-circuit/11_01.jpg","caption":"open_circuit detection — board 11, #1 (green = ground truth, red = prediction)"}],"purpose":"Full-board images were too large to pass directly to the object detector. I tiled the training images and built an inference flow that scans the board and merges duplicate detections.","concept":"The training process creates 600px tiles. Inference uses overlapping windows, then NMS to consolidate detections. A Flask tool supports batch checks and human feedback. README metrics are project evaluation results, not a guarantee across all board types.","outcome":"The project README reports 82% mAP and 100% precision and shows validation on held-out board types. The workflow covers tiling, whole-board scanning, result consolidation, and feedback.","tech":[{"group":"Image Processing","items":[{"name":"Image Tiling","desc":"Slice 600px tiles centered on each defect box, keep a box only if ≥40% of its area is inside the tile, re-normalize to 0–1; defect ratio rises from ~2% to ~12%, the make-or-break step of the project"},{"name":"Pascal VOC Parsing","desc":"Parse bndbox with xml.etree.ElementTree and convert pixel coordinates to the 0–1 normalized form Custom Vision requires"}]},{"group":"Cloud AI Services","items":[{"name":"Azure Custom Vision SDK","desc":"Full flow via the Python SDK: create project (compact domain), batch-upload images with regions, Advanced Training, publish, export TensorFlow; Advanced was chosen over Quick Train on purpose"},{"name":"model.pb Export and Colab Loading","desc":"Export the frozen graph model.pb (input Placeholder:0, output model_outputs:0), load it in Colab with tf.compat.v1; the YOLO-style anchor/NMS decoding reuses the official object_detection.py"}]},{"group":"Inference and Validation","items":[{"name":"Tiled Inference + NMS","desc":"Detect a full board tile by tile, map predictions back to the original image, then drop duplicate boxes from overlapping tiles with NMS at IoU 0.3"},{"name":"Held-out Validation","desc":"Generalization test on 106 images from board types 09–12 that never appeared in training, drawing green (ground truth) and red (prediction) boxes; 538 ground-truth defects against 509 predicted boxes, validating performance on new boards rather than trusting the cross-validation numbers alone"}]},{"group":"Application Tooling","items":[{"name":"Batch inspection UI","desc":"Local Flask web app: drag many boards for batch detection, draw the three defect classes in distinct colors, summarize NG/OK and per-class counts, export CSV"},{"name":"Human-feedback loop","desc":"Detections can be marked as false positive or missed and saved as corrections; after human review/approval, only approved data is used to retrain — an active-learning loop"}]}],"github":""}}', 6);
INSERT OR REPLACE INTO projects (id, zh, en, sort_order) VALUES ('qmk-stm32-keyboard', '{"id":"qmk-stm32-keyboard","cover":"/images/qmk-stm32-keyboard/numpad-hero.jpg","category":"大學校外作品","title":"開源硬體整合：QMK x STM32 數字鍵盤","period":"2026","description":"以 STM32F103 執行 QMK 數字鍵盤韌體，整合 USB HID、RGB Matrix 與 VIA/VIAL 改鍵。PCB 是以既有開源設計為基礎改版；我調整 QMK/ChibiOS HAL 設定並處理編譯問題。","tags":["STM32 / Cortex-M","QMK / ChibiOS HAL","USB HID · STM32duino","WS2812B RGB Matrix","EasyEDA Pro"],"detail":{"images":[{"src":"/images/qmk-stm32-keyboard/numpad-top.jpg","caption":"完成品俯視"},{"src":"/images/qmk-stm32-keyboard/numpad-hero.jpg","caption":"與主鍵盤並用"}],"purpose":"我想把 QMK 韌體用在 STM32 數字鍵盤上，過程中需要對齊鍵盤設定與 ChibiOS HAL 的 MCU 設定。","concept":"韌體以 STM32F103 為目標，調整 chconf、halconf 和 mcuconf，並整合 USB HID、RGB Matrix 及 VIA/VIAL。PCB 沿用既有開源設計再修改，不是從零開始設計。","outcome":"完成韌體建置與鍵盤功能整合。這裡描述的是專案設定和功能，不宣稱晶片型號讀取或延遲量測結果。","tech":[{"group":"嵌入式韌體","items":[{"name":"HAL 外設配置","desc":"以 LLM 輔助偵錯工具逆向工程並重構 ChibiOS chconf / halconf / mcuconf 三件組，解決開源 QMK 框架與 STM32F103 硬體間的編譯失敗與時序衝突；正確設定 USB、GPIO 時鐘來源與 PLL，掌握 RTOS tick 與外設初始化順序的依賴關係"},{"name":"鍵盤矩陣掃描","desc":"設計 5×4 ROW2COL 矩陣搭配 5 ms debounce，以最少 IO 支援 17 鍵；理解鬼鍵（ghost key）成因與二極體防護原理"},{"name":"RGB Matrix 驅動","desc":"整合 WS2812B 逐鍵定址，掌握 Hue/Sat/Val 三維色彩控制；設定最大亮度 120 防 USB 過流，理解動畫模式切換與 SPI 時序配置"},{"name":"Layer 與 tap-hold","desc":"以 LT() 實現長按切層、短按輸入，理解 QMK tap-hold 決策窗口（tapping_term）對打字手感的影響與調整方式"}]},{"group":"PCB 設計","items":[{"name":"MCU 外圍電路設計","desc":"在既有開源 PCB 基礎上確認 STM32F103 的 USB 連接、100 nF 去耦電容與燒錄設定；以 EasyEDA Pro 完成改版與送廠資料"}]}],"github":"https://github.com/Jcsk7049/qmk-stm32-keyboard","video":"UQ_tA-CO8Yw"}}', '{"id":"qmk-stm32-keyboard","cover":"/images/qmk-stm32-keyboard/numpad-hero.jpg","category":"大學校外作品","title":"Open-Source Hardware Integration: QMK × STM32 Numpad","period":"2026","description":"A QMK numpad firmware project targeting STM32F103, with USB HID, RGB Matrix, and VIA/VIAL remapping. The PCB revises an existing open-source design. I adjusted QMK/ChibiOS HAL settings and resolved build issues.","tags":["STM32 / Cortex-M","QMK / ChibiOS HAL","USB HID · STM32duino","WS2812B RGB Matrix","EasyEDA Pro"],"detail":{"images":[{"src":"/images/qmk-stm32-keyboard/numpad-top.jpg","caption":"Completed numpad — top view"},{"src":"/images/qmk-stm32-keyboard/numpad-hero.jpg","caption":"In use alongside main keyboard"}],"purpose":"I wanted to run QMK firmware on an STM32 numpad and had to align the keyboard configuration with the ChibiOS HAL settings.","concept":"The firmware targets STM32F103 and configures chconf, halconf, and mcuconf alongside USB HID, RGB Matrix, and VIA/VIAL. The PCB is a revision of an existing open-source design, not a from-scratch layout.","outcome":"The firmware build and keyboard features are integrated. This describes the project configuration and features; it does not claim chip readback or latency measurements.","tech":[{"group":"Embedded Firmware","items":[{"name":"HAL Peripheral Configuration","desc":"Reverse-engineered and restructured ChibiOS chconf/halconf/mcuconf triple config using LLM-assisted debugging to resolve compilation failures and timing conflicts between the open-source QMK framework and STM32F103 hardware; correctly set USB, GPIO clock sources, and PLL; understood RTOS tick and peripheral initialization ordering dependencies"},{"name":"Keyboard Matrix Scanning","desc":"Designed 5×4 ROW2COL matrix with 5ms debounce supporting 17 keys on minimal IO; understood ghost key causes and diode protection principles"},{"name":"RGB Matrix Driver","desc":"Integrated WS2812B per-key addressing; Hue/Sat/Val 3D color control; set max brightness 120 to prevent USB overcurrent; understood animation mode switching and SPI timing"},{"name":"Layer & Tap-Hold","desc":"LT() for hold-to-layer, tap-to-input; understanding how QMK tap-hold decision window (tapping_term) affects typing feel and tuning"}]},{"group":"PCB Design","items":[{"name":"MCU Peripheral Circuit","desc":"Verified the STM32F103 USB connection, 100nF decoupling capacitors, and flashing configuration on the existing open-source PCB; completed the adaptation and fabrication files in EasyEDA Pro"}]}],"github":"https://github.com/Jcsk7049/qmk-stm32-keyboard","video":"UQ_tA-CO8Yw"}}', 7);
INSERT OR REPLACE INTO projects (id, zh, en, sort_order) VALUES ('team7645-cms', '{"id":"team7645-cms","cover":"/images/team7645-cms/cover.png","category":"大學校外作品","title":"FRC 7645 — 官網與後台 CMS","period":"2025","description":"參與 FRC 7645 官網與 CMS 開發，完成首頁改版、訪客留言管理、組別身分介面、程式碼拆分與 The Blue Alliance 資料快取。團隊內容由 Firebase 管理，網站可在線瀏覽。","tags":["React","Firebase","Vite","Cloudflare Pages","Code Splitting","localStorage 快取"],"detail":{"purpose":"團隊需要能自行更新賽事、成員與公告的網站。我參與官網功能與 CMS 的整理，讓部分內容能由管理介面維護。","concept":"網站使用 React 與 Firebase。工作包含首頁、訪客留言到 CMS 的流程、組別顯示設定、路由程式碼拆分，以及 The Blue Alliance 資料快取。","outcome":"官網與 CMS 已部署，訪客可瀏覽團隊資訊並留言；管理者可在 CMS 查看與處理留言。","tech":[{"group":"效能優化","items":[{"name":"Code Splitting & Lazy Loading","desc":"Vite 動態 import 拆分路由層級 chunk，React.lazy + Suspense 按需載入"},{"name":"TBA API localStorage 快取","desc":"以端點 + 查詢字串為 key 的 30 天快取層；每次請求驗證新鮮度；減少重複請求"}]},{"group":"功能系統","items":[{"name":"留言系統","desc":"Contact 表單 → Firestore `messages` collection 端對端；CMS MessagesPanel Tab 讓管理員直接查看與刪除留言，不需開 Firebase Console"},{"name":"Firestore 安全規則（messages）","desc":"`allow create: if true` 讓訪客可送出留言；`allow read, delete` 限定 admin / teacher；`allow update: if false` 防止竄改。補上這條前，未驗證寫入會被 Firebase 預設拒絕"},{"name":"組別身分系統","desc":"Admin 多選 pill UI 設定 `showInDivision`；TeamGroup 組件自動過濾並渲染對應成員，取代手動維護靜態名單"}]},{"group":"前端組件","items":[{"name":"TeamTimeline.jsx / Competition.jsx","desc":"TeamTimeline 從資料陣列渲染里程碑時間軸，與頁面佈局解耦；Competition 消費 TBA 快取，獨立處理 loading / error / empty"},{"name":"浮動贊助商泡泡","desc":"CSS keyframe animation 取代 marquee，消除捲動卡頓"}]},{"group":"CMS 重整","items":[{"name":"模組整併與新 Tab","desc":"Carousel + Cards → Homepage Management；Contact + Socials → 聯絡模組；補回 Advisor Tab；新增留言管理 Tab 與作者/組別拆分欄位"}]}],"demo":"https://nkhs.team7645.com/","github":"https://github.com/Jcsk7049/team7645-website"}}', '{"id":"team7645-cms","cover":"/images/team7645-cms/cover.png","category":"大學校外作品","title":"FRC 7645 — Team Website & CMS","period":"2025","description":"Contributed to the FRC 7645 website and CMS: homepage updates, visitor-message management, division identity UI, code splitting, and The Blue Alliance data caching. Firebase manages team content, and the site is live.","tags":["React","Firebase","Vite","Cloudflare Pages","Code Splitting","localStorage Cache"],"detail":{"purpose":"The team needed a site where staff could update events, members, and announcements. I worked on the website and CMS so some content could be maintained through an admin interface.","concept":"Built with React and Firebase. My work included the homepage, visitor messages in the CMS, division display settings, route code splitting, and caching The Blue Alliance data.","outcome":"The website and CMS are deployed. Visitors can browse team information and send a message; administrators can review and manage messages in the CMS.","tech":[{"group":"Performance","items":[{"name":"Code Splitting & Lazy Loading","desc":"Vite dynamic imports for route-level chunks + React.lazy / Suspense for on-demand loading; JS bundle 2.7MB → 820KB (~70%)"},{"name":"TBA API localStorage Cache","desc":"30-day cache keyed by endpoint + query string; freshness validated per request; eliminates competition-day redundant fetches and rate-limit risk"}]},{"group":"Feature Systems","items":[{"name":"Messaging System","desc":"Contact form → Firestore `messages` collection end-to-end; CMS MessagesPanel Tab for admin review and deletion without Firebase Console access"},{"name":"Firestore Security Rule (messages)","desc":"`allow create: if true` for unauthenticated visitor submissions; `allow read, delete` scoped to admin / teacher; `allow update: if false` to prevent tampering. Without this rule Firebase''s default deny-all blocks unauthenticated writes"},{"name":"Division Identity System","desc":"Admin multi-select pill sets `showInDivision`; TeamGroup auto-filters and renders members from this field, replacing manually maintained static rosters"}]},{"group":"Deployment & DevOps","items":[{"name":"Cloudflare Pages CI/CD","desc":"PR preview + production deploys on main merge; nkhs.team7645.com custom domain"}]},{"group":"Frontend Components","items":[{"name":"TeamTimeline.jsx / Competition.jsx","desc":"TeamTimeline renders milestone timeline from a data array, decoupled from layout; Competition consumes TBA cache and handles loading / error / empty states independently"},{"name":"Floating Sponsor Bubbles","desc":"CSS keyframe animation replacing marquee; eliminated scroll jank"}]},{"group":"CMS Restructure","items":[{"name":"Module Consolidation & New Tabs","desc":"Carousel + Cards → Homepage Management; Contact + Socials → single module; restored Advisor Tab; added MessagesPanel tab and author/division split fields"}]},{"group":"Dev Infrastructure","items":[{"name":"CLAUDE.md Workspace Memory","desc":"Documented project architecture, naming conventions, and off-limits zones in CLAUDE.md with a fixed directory structure — maintaining consistent LLM context across sessions and preventing convention drift across refactor cycles"}]}],"demo":"https://nkhs.team7645.com/","github":"https://github.com/Jcsk7049/team7645-website"}}', 8);
INSERT OR REPLACE INTO projects (id, zh, en, sort_order) VALUES ('whack-a-mole', '{"id":"whack-a-mole","cover":"/images/whack-a-mole/machines-group.jpg","category":"高職選手作品","title":"無線打地鼠機 (特教組教具)","period":"2021 – 2022","description":"為南港高工特教組製作無線打地鼠教具，以 ESP32/ESP-NOW 連接一台主機與四台遊戲機。除錯時先處理繼電器線圈反電動勢造成的元件損壞，再改善 7805 過熱問題；成品獲特教組感謝狀。","tags":["ESP32","ESP-NOW","電路設計","3D列印","Arduino"],"detail":{"purpose":"特教組需要一套方便操作與維修的互動教具。我們選擇打地鼠形式，做成一台主機控制四台遊戲機的無線系統。","concept":"ESP32 透過 ESP-NOW 傳送遊戲狀態，按鈕與繼電器控制各機台。除錯時在繼電器線圈加上 1N4001 飛輪二極體處理反電動勢，並針對 7805 線性穩壓器的發熱檢查負載與散熱。","outcome":"五台機台完成組裝並交給特教組使用，專案獲感謝狀。製作過程也讓我實際處理無線通訊、繼電器保護和線性穩壓發熱問題。","images":[{"src":"/images/whack-a-mole/machines-group.jpg","caption":"五台機台（一主四從）亮燈實況——黃、紅、藍三色 LED 按鈕"},{"src":"/images/whack-a-mole/machine-single.jpg","caption":"單台成品外觀：鋁方管外殼 + 木板上蓋 + 大型 LED 按鈕"},{"src":"/images/whack-a-mole/circuit-schematic.jpg","caption":"電路設計手稿：11.1V → 7805 → ESP32 → 9013 電晶體 → 繼電器 → LED"},{"src":"/images/whack-a-mole/circuit-board.jpg","caption":"電路實體：ESP32 + 繼電器接線，含 1N4001 飛輪二極體保護"},{"src":"/images/whack-a-mole/esp32-buttons.jpg","caption":"五台機台 LED 按鈕特寫：黃、紅、藍三色大型按鈕，學生手按示範"},{"src":"/images/whack-a-mole/esp32-circuit.jpg","caption":"ESP32 + 繼電器電路板：含藍色繼電器模組與 18650 電池接線"},{"src":"/images/whack-a-mole/esp32-internal.jpg","caption":"機台內部組裝：ESP32 電路板固定於 3D 列印框架，磁吸底蓋設計"}],"tech":[{"group":"無線通訊","items":[{"name":"多機 P2P 協同","desc":"設計一主四從廣播狀態機，掌握 ESP-NOW 在無路由器環境下的設備配對、廣播重置與斷線重連機制；以 Arduino C++ 實作主從邏輯"}]},{"group":"電路設計","items":[{"name":"電晶體電流放大","desc":"計算 9013 NPN 基極限流電阻確保飽和導通，解決 ESP32 GPIO 驅動電流不足以直接驅動繼電器的問題"},{"name":"高壓負載隔離","desc":"繼電器將 3.3V 控制端與 11.1V 負載端完全隔離，理解接點容量限制與切換頻率對接點壽命的影響"},{"name":"反電動勢保護","desc":"1N4001 飛輪二極體並聯繼電器線圈，吸收關斷瞬間的感性反電動勢；透過實際排查 ESP32 損壞問題後才理解其必要性"},{"name":"電源穩壓去耦","desc":"7805 線性穩壓搭配陶瓷去耦電容，消除馬達/繼電器切換產生的電源毛刺；實際排查 7805 過熱原因，理解線性穩壓的功耗限制"}]},{"group":"面向維修的機構設計","items":[{"name":"快速替換結構","desc":"以「化繁為簡」為原則，上蓋從 3D 列印改為木板縮短替換時間；強力磁鐵底蓋免工具換電池，針對特教場景的現場維修需求做針對性設計"}]}],"github":""}}', '{"id":"whack-a-mole","cover":"/images/whack-a-mole/machines-group.jpg","category":"高職選手作品","title":"Wireless Whack-a-Mole (Special Ed Aid)","period":"2021 – 2022","description":"Built a wireless whack-a-mole teaching aid for the Nangang VHS special education department. ESP32/ESP-NOW connects one master to four game units. I fixed component damage caused by relay-coil back-EMF, then addressed 7805 overheating. The department issued a letter of appreciation.","tags":["ESP32","ESP-NOW","Circuit Design","3D Printing","Arduino"],"detail":{"purpose":"The special education department needed an interactive teaching aid that was easy to operate and maintain. We chose a whack-a-mole format with one master controlling four wireless units.","concept":"ESP32 boards send game states over ESP-NOW; buttons and relays control each unit. I added a 1N4001 flyback diode across relay coils to handle back-EMF, then checked the load and heat dissipation around the 7805 linear regulator.","outcome":"Five units were assembled and delivered to the department, which issued a letter of appreciation. I worked through wireless communication, relay protection, and linear-regulator heating.","images":[{"src":"/images/whack-a-mole/machines-group.jpg","caption":"All 5 units (1 master + 4 slaves) lit up — yellow, red, blue LED buttons"},{"src":"/images/whack-a-mole/machine-single.jpg","caption":"Single unit: aluminum tube enclosure + wood top cover + large LED button"},{"src":"/images/whack-a-mole/circuit-schematic.jpg","caption":"Circuit design sketch: 11.1V → 7805 → ESP32 → 9013 transistor → relay → LED"},{"src":"/images/whack-a-mole/circuit-board.jpg","caption":"Circuit board: ESP32 + relay wiring with 1N4001 flyback diode protection"},{"src":"/images/whack-a-mole/esp32-buttons.jpg","caption":"Close-up of 5-unit LED buttons: yellow/red/blue large buttons, student demonstration"},{"src":"/images/whack-a-mole/esp32-circuit.jpg","caption":"ESP32 + relay board: blue relay modules and 18650 battery wiring"},{"src":"/images/whack-a-mole/esp32-internal.jpg","caption":"Internal assembly: ESP32 board mounted in 3D-printed frame, magnetic bottom cover"}],"tech":[{"group":"Wireless Communication","items":[{"name":"Multi-Unit P2P Coordination","desc":"Designed 1-master 4-slave broadcast state machine; mastered ESP-NOW device pairing, broadcast reset, and auto-reconnect in a router-free environment; implemented master/slave logic in Arduino C++"}]},{"group":"Circuit Design","items":[{"name":"Transistor Current Amplification","desc":"Calculated 9013 NPN base current-limiting resistor for saturation conduction, solving ESP32 GPIO current insufficient to directly drive relay"},{"name":"High-Voltage Load Isolation","desc":"Relay fully isolates 3.3V control from 11.1V load; understanding contact capacity limits and switching frequency effects on contact lifespan"},{"name":"Back-EMF Protection","desc":"1N4001 flyback diode across relay coil absorbs inductive back-EMF on turn-off; necessity understood only after diagnosing actual ESP32 failure in the field"},{"name":"Power Regulation & Decoupling","desc":"7805 linear regulator with ceramic decoupling capacitors to eliminate power glitches from motor/relay switching; diagnosed 7805 overheating and understood linear regulator power dissipation limits"}]},{"group":"Maintenance-Oriented Mechanical Design","items":[{"name":"Quick-Swap Structure","desc":"\"Keep it simple\" principle: top cover changed from 3D print to wood to shorten replacement time; magnetic bottom cover for tool-free battery access, designed specifically for on-site special education maintenance needs"}]}],"github":""}}', 9);
INSERT OR REPLACE INTO projects (id, zh, en, sort_order) VALUES ('team-robot', '{"id":"team-robot","cover":"/images/team-robot/competition.jpg","category":"高職選手作品","title":"集體創作競賽機器人","period":"2022","description":"代表南港高工參加 2022 年第 52 屆全國技能競賽集體創作職類。三人製作夾取機器人，我負責 24V 配電、繼電器 H 橋與全車配線；隊友負責機構加工和控制程式。","tags":["競賽機器人","繼電器控制","機構設計","三人團隊"],"detail":{"purpose":"競賽要求三人合作，在限定時間內完成能移動並夾取物件的機器人。我負責整車電路，與機構和程式組員一起整合。","concept":"我設計繼電器 H 橋、規劃 24V 配電並完成全車拉線。隊友負責底盤與夾爪加工，以及控制程式。","outcome":"代表學校完成第 52 屆全國技能競賽集體創作職類作品。這次合作讓我在短時間內把電路、機構與控制整合成可操作的作品。","tech":[{"group":"電路設計","items":[{"name":"繼電器 H 橋驅動","desc":"以兩個繼電器組成單軸 H 橋，切換馬達電流方向控制前進/後退；理解 H 橋同側繼電器同時導通的短路風險與互鎖設計"},{"name":"24V 高壓系統配線","desc":"鉛酸電池組高電流配線規範，理解導線截面積與連接器接觸電阻對功率損耗的影響"}]},{"group":"機構設計","items":[{"name":"通用夾爪設計","desc":"夾口弧面段貼合圓柱、平面段夾持方形物件，在不換夾具的前提下兼容兩種截面形狀，理解幾何約束對夾持穩定性的設計原則"}]}],"github":"","images":[{"src":"/images/team-robot/cad-drawing.jpg","caption":"機器人 3D 設計稿與夾取物規格圖（圓柱 & 正方體）"},{"src":"/images/team-robot/robot-side.jpg","caption":"完成品側視圖 — 夾爪機構與底盤結構"},{"src":"/images/team-robot/circuit-schematic.jpg","caption":"繼電器 H 橋電路設計圖（24V 四馬達驅動）"},{"src":"/images/team-robot/competition.jpg","caption":"第 52 屆全國技能競賽現場操作"}]}}', '{"id":"team-robot","cover":"/images/team-robot/competition.jpg","category":"高職選手作品","title":"Team-Built Competition Robot","period":"2022","description":"Represented Nangang VHS at the 2022 52nd National Skills Competition in the Team Project category. Three students built a gripper robot. I handled 24V power distribution, the relay H-bridge, and vehicle wiring; teammates handled mechanical fabrication and control software.","tags":["Competition Robot","Relay Control","Mechanical Design","3-Person Team"],"detail":{"purpose":"The competition asked a three-person team to build a robot that could move and grip objects within a limited time. I handled the electrical system and integrated it with the mechanical and software work.","concept":"I designed the relay H-bridge, planned 24V power distribution, and wired the robot. Teammates fabricated the chassis and gripper and wrote the control software.","outcome":"We completed the school project for the 52nd National Skills Competition. The work required integrating electrical, mechanical, and control systems under a short deadline.","tech":[{"group":"Circuit Design","items":[{"name":"Relay H-Bridge Drive","desc":"Two relays per axis form a single-axis H-bridge to switch motor current direction; understanding H-bridge same-side relay simultaneous conduction short-circuit risk and interlock design"},{"name":"24V High-Voltage Wiring","desc":"Lead-acid battery pack high-current wiring standards; understanding the effect of wire cross-section and connector contact resistance on power loss"}]},{"group":"Mechanical Design","items":[{"name":"Universal Gripper Design","desc":"Curved gripping surface for cylinders, flat surface for rectangular objects — accommodating two cross-sections without tool changes; understanding geometric constraints for gripping stability"}]}],"github":"","images":[{"src":"/images/team-robot/cad-drawing.jpg","caption":"Robot 3D design and object specs (cylinder & rectangular block)"},{"src":"/images/team-robot/robot-side.jpg","caption":"Completed robot side view — gripper mechanism and chassis structure"},{"src":"/images/team-robot/circuit-schematic.jpg","caption":"Relay H-bridge circuit design (24V 4-motor drive)"},{"src":"/images/team-robot/competition.jpg","caption":"52nd National Skills Competition — field operation"}]}}', 10);
INSERT OR REPLACE INTO projects (id, zh, en, sort_order) VALUES ('swerve', '{"id":"swerve","cover":"/images/swerve/swerve-assembled-side.jpg","category":"高職選手作品","title":"Swerve Drive 全向輪控制研究","period":"2020 – 2023","frc":true,"description":"參與 FRC Swerve Drive 底盤三代迭代，工作包含 LabVIEW 運動學、齒輪傳動、CAD、CNC 與線切割。2022 年台灣鴻海區域賽獲 Innovation in Control Award。","tags":["LabVIEW","PID Control","CNC 加工","線切割","Robotics","3D 列印"],"detail":{"purpose":"團隊持續修改 Swerve Drive 底盤，從運動控制到傳動與加工逐代調整。我參與控制程式、齒輪設計和零件製作。","concept":"我以 LabVIEW 實作全向移動運動學，並參與齒輪傳動、CAD、CNC 銑削與線切割。不同屆的底盤包含多位隊員的設計與製作成果。","outcome":"2022 年底盤參加 FRC 台灣鴻海區域賽，獲 Innovation in Control Award。作品也曾參加 2020 年中科 5G 區域賽並獲 Excellence in Engineering Award。","tech":[{"group":"控制系統","items":[{"name":"向量合成運動學","desc":"以向量 X∠θ 分解平移、迴旋、弧形三種運動模式並疊加，取最大力道輪正規化輸出防馬達飽和；以 LabVIEW 圖形化實作完整演算法"},{"name":"PID 閉迴路控制","desc":"各輪獨立編碼器回饋，PID 控制轉向角度，掌握積分飽和（wind-up）與微分濾波在競賽高動態環境下的調參與穩定性取捨"}]},{"group":"機構設計","items":[{"name":"模組化傳動架構","desc":"驅動與轉向馬達孔位共用、齒輪區可換齒調整減速比，不修改鋁板即可適配不同馬達規格；三代迭代中實際驗證模組化對維修速度的提升"},{"name":"輕量化結構設計","desc":"以材料替換策略降重：內部傳動齒輪改 FDM 列印，保留馬達軸金屬件；鋁板 CNC 偷料在保持結構強度前提下減少板材用量"}]},{"group":"精密加工","items":[{"name":"CNC 數值銑削","desc":"加工傳動心軸（六角柱 & 方槽截面），以 4 爪夾盤定位，兩面分次銑削確保截面對稱；相較手工銑床大幅提升尺寸精度與批量重現性"},{"name":"數值線切割","desc":"完成 M1.25–M1.5 正齒輪與直齒斜齒輪的外形與內孔切割，掌握壓板固定、尋邊校正 XY 誤差、路徑模擬確認的完整作業流程"}]}],"github":"","images":[{"src":"/images/swerve/swerve-cad-iso.jpg","caption":"第三代 Swerve Drive — 3D CAD 等角視圖"},{"src":"/images/swerve/swerve-cad-4view.jpg","caption":"第三代 Swerve Drive — 四視圖工程圖"},{"src":"/images/swerve/swerve-assembled-top.jpg","caption":"組裝完成 — 俯視（可見齒輪傳動系統）"},{"src":"/images/swerve/swerve-assembled-side.jpg","caption":"組裝完成 — 側視（馬達與底盤結構）"},{"src":"/images/swerve/swerve-gears-internal.jpg","caption":"內部齒輪組（3D 列印齒輪 + 金屬件）"},{"src":"/images/swerve/swerve-bevel-gear.jpg","caption":"直齒斜齒輪與驅動馬達 CAD 模型"},{"src":"/images/swerve/swerve-plate-cnc.jpg","caption":"CNC 加工完成的鋁板"},{"src":"/images/swerve/swerve-gear-drill.jpg","caption":"金屬斜齒輪鑽孔加工"},{"src":"/images/swerve/swerve-wire-cut-action.jpg","caption":"線切割加工齒輪內孔（進行中）"},{"src":"/images/swerve/swerve-wire-cut-panel.jpg","caption":"線切割機控制面板 — 六角形路徑模擬"},{"src":"/images/swerve/swerve-flowchart-algo.png","caption":"LabVIEW 向量合成運動學演算法流程圖"},{"src":"/images/swerve/swerve-wiring.png","caption":"FRC 機器人電路系統配線圖"}]}}', '{"id":"swerve","cover":"/images/swerve/swerve-assembled-side.jpg","category":"高職選手作品","title":"Swerve Drive Omnidirectional Research","period":"2020 – 2023","frc":true,"description":"Worked across three iterations of an FRC swerve-drive chassis, including LabVIEW kinematics, gear transmission, CAD, CNC milling, and wire EDM. The 2022 robot received the Innovation in Control Award at the FRC Taiwan Fuhong Regional.","tags":["LabVIEW","PID Control","CNC Machining","Wire EDM","Robotics","3D Printing"],"detail":{"purpose":"The team iterated on its swerve-drive chassis, changing motion control, transmission, and fabrication between versions. I contributed to the control code, gear design, and part production.","concept":"I implemented omnidirectional kinematics in LabVIEW and worked on gear transmission, CAD, CNC milling, and wire EDM. The chassis versions represent design and fabrication work across multiple team members.","outcome":"The 2022 chassis competed at the FRC Taiwan Fuhong Regional and received the Innovation in Control Award. An earlier robot competed at the 2020 FRC Central Taiwan 5G Regional and received the Excellence in Engineering Award.","tech":[{"group":"Control System","items":[{"name":"Vector-Composition Kinematics","desc":"Decomposing translation, rotation, and arc motion modes as X∠θ vectors and superimposing them; normalizing by max-force wheel to prevent motor saturation; fully implemented in LabVIEW graphical programming"},{"name":"PID Closed-Loop Control","desc":"Per-wheel independent encoder feedback for PID steering angle control; mastering integral windup and derivative filtering tuning in high-dynamic competition environments"}]},{"group":"Mechanical Design","items":[{"name":"Modular Transmission Architecture","desc":"Drive and steering motor holes shared; gear zone swappable for reduction ratio adjustment without modifying aluminum plates; three-generation iteration validated modular design''s improvement in repair speed"},{"name":"Lightweight Structural Design","desc":"Material substitution for weight reduction: internal gears switched to FDM printing, retaining metal motor shaft gears; CNC material removal from aluminum plates while maintaining structural strength"}]},{"group":"Precision Machining","items":[{"name":"CNC Numerical Milling","desc":"Machining transmission shafts (hex & square cross-sections) with 4-jaw chuck positioning; bilateral milling for cross-sectional symmetry; significantly improved dimensional accuracy and batch reproducibility over manual milling"},{"name":"Wire EDM","desc":"M1.25–M1.5 spur and bevel gear profile and bore cutting; mastering clamp plate fixturing, edge-finding XY error correction, and path simulation verification workflow"}]}],"github":"","images":[{"src":"/images/swerve/swerve-cad-iso.jpg","caption":"Gen 3 Swerve Drive — 3D CAD isometric view"},{"src":"/images/swerve/swerve-cad-4view.jpg","caption":"Gen 3 Swerve Drive — 4-view engineering drawing"},{"src":"/images/swerve/swerve-assembled-top.jpg","caption":"Assembled — top view (gear transmission system visible)"},{"src":"/images/swerve/swerve-assembled-side.jpg","caption":"Assembled — side view (motors and chassis structure)"},{"src":"/images/swerve/swerve-gears-internal.jpg","caption":"Internal gear set (3D printed gears + metal parts)"},{"src":"/images/swerve/swerve-bevel-gear.jpg","caption":"Bevel gear and drive motor CAD model"},{"src":"/images/swerve/swerve-plate-cnc.jpg","caption":"CNC-machined aluminum plate"},{"src":"/images/swerve/swerve-gear-drill.jpg","caption":"Metal bevel gear drilling"},{"src":"/images/swerve/swerve-wire-cut-action.jpg","caption":"Wire EDM cutting gear bore (in progress)"},{"src":"/images/swerve/swerve-wire-cut-panel.jpg","caption":"Wire EDM control panel — hexagonal path simulation"},{"src":"/images/swerve/swerve-flowchart-algo.png","caption":"LabVIEW vector-composition kinematics algorithm flowchart"},{"src":"/images/swerve/swerve-wiring.png","caption":"FRC robot electrical system wiring diagram"}]}}', 11);
